using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using Mori;

namespace MoriDesk {
 internal static class CanvasDrawingTests {
  static void Reject(Action action,Action<bool,string> check,string label){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}check(rejected,label);}
  static IEnumerable<DependencyObject> Descendants(DependencyObject root){yield return root;for(int i=0;i<VisualTreeHelper.GetChildrenCount(root);i++)foreach(var child in Descendants(VisualTreeHelper.GetChild(root,i)))yield return child;}
  static void Draw(FreeCanvasWindow window,string kind,params Point[] points){if(!window.BeginDrawingForTests(kind,points[0]))throw new Exception("Canvas drawing gesture failed to start: "+kind);for(int i=1;i<points.Length-1;i++)window.UpdateDrawingForTests(points[i]);window.EndDrawingForTests(points[points.Length-1]);}
  static Color Pixel(BitmapSource image,int x,int y){byte[] pixel=new byte[4];image.CopyPixels(new Int32Rect(x,y,1,1),pixel,4,0);return Color.FromArgb(pixel[3],pixel[2],pixel[1],pixel[0]);}
  static RenderTargetBitmap Render(FrameworkElement content,int width,int height){content.Width=width;content.Height=height;content.Measure(new Size(width,height));content.Arrange(new Rect(0,0,width,height));content.UpdateLayout();var bitmap=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);bitmap.Render(content);return bitmap;}
  static void SaveImage(BitmapSource image,string path){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using(var output=File.Create(path))encoder.Save(output);}
  internal static void Run(string root,Action<bool,string> check){
   Directory.CreateDirectory(root);var app=Application.Current??new Application();string theme=Theme.Current,accent=Theme.AccentKey;var shutdown=app.ShutdownMode;app.ShutdownMode=ShutdownMode.OnExplicitShutdown;
   FreeCanvasWindow window=null,reloaded=null,saveGesture=null;string data=Path.Combine(root,"profile");
   try{
    Theme.Set("light");window=new FreeCanvasWindow(data,new Settings());
    var content=(FrameworkElement)window.Content;Render(content,1120,700);
    var buttons=Descendants(content).OfType<Button>().Where(b=>b.Name.StartsWith("CanvasTool_",StringComparison.Ordinal)).ToArray();
    check(new[]{"select","stroke","line","arrow","rectangle","ellipse","text"}.All(kind=>buttons.Count(b=>b.Name=="CanvasTool_"+kind)==1),"canvas toolbar exposes one named selectable button for every basic drawing tool");
    foreach(string kind in new[]{"stroke","line","arrow","rectangle","ellipse","select"}){buttons.Single(b=>b.Name=="CanvasTool_"+kind).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(window.ModeForTests==kind,"real toolbar click switches to "+kind);}
    check(Descendants(content).OfType<FrameworkElement>().Any(e=>e.Name=="CanvasInkColor")&&Descendants(content).OfType<FrameworkElement>().Any(e=>e.Name=="CanvasStrokeWidth"),"drawing toolbar provides discoverable color and width controls");
    window.SetDrawingStyleForTests("#2764B0",6);
    Draw(window,"stroke",new Point(30,40),new Point(42,55),new Point(60,40));var stroke=window.DocumentForTests.Items.Single();
    check(stroke.Kind=="stroke"&&stroke.Points.Count>=3&&stroke.Points[0].X==30&&stroke.Points.Last().X==60&&stroke.Color=="#2764B0"&&stroke.Stroke==6&&window.ModeForTests=="stroke","shared pointer gesture stores freehand points, style and final mouse-up position without leaving drawing mode");
    Draw(window,"line",new Point(80,35),new Point(145,55));Draw(window,"arrow",new Point(370,65),new Point(510,65));Draw(window,"rectangle",new Point(300,90),new Point(180,30));Draw(window,"ellipse",new Point(580,30),new Point(690,100));
    check(window.ItemCount==5&&window.DocumentForTests.Items.Select(i=>i.Kind).SequenceEqual(new[]{"stroke","line","arrow","rectangle","ellipse"}),"each actual drawing gesture commits exactly one ordered annotation");
    var rectangle=window.DocumentForTests.Items.Single(i=>i.Kind=="rectangle");var ellipse=window.DocumentForTests.Items.Single(i=>i.Kind=="ellipse");
    check(rectangle.Bounds().Contains(new Point(180,30))&&rectangle.Bounds().Contains(new Point(300,90))&&ellipse.Bounds().Contains(new Point(635,65)),"reverse-direction rectangle and ellipse retain valid normalized geometry");
    check(window.HitForTests(new Point(240,60))==null&&window.HitForTests(new Point(635,65))==null,"empty interiors of outline shapes do not intercept selection of content beneath them");
    check(window.HitForTests(new Point(180,60))==rectangle&&window.HitForTests(new Point(690,65))==ellipse,"outline shapes can be picked by their visible edges");
    var arrow=window.DocumentForTests.Items.Single(i=>i.Kind=="arrow");check(window.HitForTests(new Point(440,65))==arrow,"arrow shaft participates in actual canvas picking");
    var painted=Render(content,1120,700);var offset=window.SurfaceForTests.TranslatePoint(new Point(0,0),content);var background=((SolidColorBrush)Theme.Brush("Canvas")).Color;Func<int,int,Color> at=(x,y)=>Pixel(painted,x+(int)Math.Round(offset.X),y+(int)Math.Round(offset.Y));
    check(at(240,60)==background&&at(635,65)==background&&at(180,60)!=background,"rendered shapes have colored strokes but no opaque interior fill");
    bool head=false;for(int y=45;y<62;y++)for(int x=480;x<511;x++)if(at(x,y)!=background)head=true;check(head,"rendered arrow includes a visible non-collinear head, not merely a line");
    int before=window.ItemCount;Draw(window,"line",new Point(700,120),new Point(700,120));Draw(window,"arrow",new Point(700,120),new Point(700,120));
    check(window.ItemCount==before,"click without movement does not create a degenerate line or arrow");Draw(window,"stroke",new Point(725,120));check(window.ItemCount==before+1&&window.DocumentForTests.Items.Last().Points.Count==1,"single pen click creates a visible saved dot");
    window.BeginDrawingForTests("rectangle",new Point(710,150));window.UpdateDrawingForTests(new Point(790,220));window.CancelGestureForTests();check(window.ItemCount==before+1,"cancelling an unfinished outline never commits a hidden draft");
    window.BeginDrawingForTests("rectangle",new Point(710,150));window.UpdateDrawingForTests(new Point(790,220));window.SurfaceForTests.RaiseEvent(new MouseEventArgs(Mouse.PrimaryDevice,Environment.TickCount){RoutedEvent=UIElement.LostMouseCaptureEvent});check(window.ItemCount==before+1&&window.BeginDrawingForTests("ellipse",new Point(710,150)),"actual lost-capture route cancels a draft and permits the next drawing gesture");window.CancelGestureForTests();
    window.BeginDrawingForTests("arrow",new Point(710,150));window.UpdateDrawingForTests(new Point(790,220));typeof(Window).GetMethod("OnDeactivated",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(window,new object[]{EventArgs.Empty});check(window.ItemCount==before+1&&window.BeginDrawingForTests("line",new Point(710,150)),"actual window deactivation route discards unfinished drawing without a stuck gesture");window.CancelGestureForTests();
    var original=stroke.Copy();window.MoveForTests(stroke.Id,new Vector(11,-7));var moved=window.DocumentForTests.Items.Single(i=>i.Id==stroke.Id);
    check(moved.Points.Select(p=>p.X).SequenceEqual(original.Points.Select(p=>p.X+11))&&moved.Points.Select(p=>p.Y).SequenceEqual(original.Points.Select(p=>p.Y-7))&&original.Points[0].X==30,"moving freehand translates every point and leaves the deep undo snapshot intact");window.UndoForTests();
    var restored=window.DocumentForTests.Items.Single(i=>i.Id==stroke.Id);check(restored.Points.Select(p=>p.X).SequenceEqual(original.Points.Select(p=>p.X))&&restored.Points.Select(p=>p.Y).SequenceEqual(original.Points.Select(p=>p.Y)),"one move undo restores exact freehand geometry instead of a shared mutated list");
    window.DeleteForTests(rectangle.Id,ellipse.Id);check(!window.DocumentForTests.Items.Any(i=>i.Id==rectangle.Id||i.Id==ellipse.Id),"multi-delete removes only selected drawing objects");window.UndoForTests();check(window.DocumentForTests.Items[3].Id==rectangle.Id&&window.DocumentForTests.Items[4].Id==ellipse.Id,"multi-delete undo restores original object ordering");
    var priorLine=window.DocumentForTests.Items.Single(i=>i.Kind=="line");window.SetDrawingStyleForTests("#A54E6D",3);Draw(window,"line",new Point(80,160),new Point(150,160));
    check(priorLine.Color=="#2764B0"&&priorLine.Stroke==6&&window.DocumentForTests.Items.Last().Color=="#A54E6D"&&window.DocumentForTests.Items.Last().Stroke==3,"changing drawing settings changes only the next annotation, not existing content");
    check(window.SaveForTests()&&!window.DirtyForTests,"real drawing gestures persist atomically and clear dirty state only on successful save");string project=window.DocumentForTests.Id;
    var store=new FreeCanvasStore(data);var saved=store.Load(project);check(saved.Items.Count==window.ItemCount&&saved.Items.First().Points.Count==restored.Points.Count&&saved.Items.Last().Color=="#A54E6D","reload round-trips freehand, arrow, geometry and annotation style");
    var cloned=store.SaveAs(saved,"绘图独立副本");cloned.Items.First().Points[0].X+=100;check(saved.Items.First().Points[0].X==30,"save-as makes independent freehand point lists");
    var bad=store.Load(project);bad.Items.First().Points[0].X=double.NaN;Reject(()=>store.Save(bad),check,"non-finite freehand coordinates cannot enter a project manifest");bad=store.Load(project);bad.Items.First().Points=new List<FreeCanvasPoint>();Reject(()=>store.Save(bad),check,"empty freehand strokes are rejected");bad=store.Load(project);bad.Items.First().Points=Enumerable.Range(0,100001).Select(i=>new FreeCanvasPoint{X=i,Y=i}).ToList();Reject(()=>store.Save(bad),check,"excessive per-stroke point count is bounded to keep corrupted projects safe");bad=store.Load(project);bad.Items.Single(i=>i.Kind=="arrow").Stroke=-1;Reject(()=>store.Save(bad),check,"invalid arrow width is rejected before any file write");
    check(store.Load(project).Items.Count==saved.Items.Count,"invalid records never overwrite the last intact drawing project");
    var oversized=store.Load(project);var points=Enumerable.Range(0,100000).Select(i=>new FreeCanvasPoint{X=i,Y=i}).ToList();oversized.Items=new List<FreeCanvasItem>();for(int i=0;i<11;i++)oversized.Items.Add(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="stroke",Color="auto",Stroke=2,Points=points});Reject(()=>FreeCanvasStore.Validate(oversized),check,"cumulative stroke points are bounded even when every individual stroke is within its own limit");
    SaveImage(Render(content,1120,700),Path.Combine(root,"drawing-tools-light.png"));Theme.Set("dark");SaveImage(Render(content,1120,700),Path.Combine(root,"drawing-tools-dark.png"));Theme.Set("light");
    SaveImage(Render(content,860,600),Path.Combine(root,"drawing-tools-compact.png"));check(buttons.All(b=>b.TranslatePoint(new Point(b.ActualWidth,0),content).X<=860),"drawing tools remain inside the canvas at its minimum supported width");
    var resize=rectangle.Copy();var bounds=resize.Bounds();FreeCanvasGeometry.Resize(resize,rectangle,"se",new Point(bounds.Left+bounds.Width*2,bounds.Top+bounds.Height*3),1);check(resize.Bounds().Width>bounds.Width&&resize.Bounds().Height>bounds.Height,"shape resize changes both dimensions while keeping valid endpoint bounds");
    var resizedStroke=restored.Copy();FreeCanvasGeometry.Resize(resizedStroke,restored,"nw",new Point(-70,-40),1);check(resizedStroke.Points.Count==restored.Points.Count&&resizedStroke.Bounds().Width>restored.Bounds().Width&&restored.Points[0].X==30&&resizedStroke.Stroke==restored.Stroke,"freehand reverse-corner resize transforms a deep point copy while preserving pen width");
    var dot=window.DocumentForTests.Items.Single(i=>i.Kind=="stroke"&&i.Points.Count==1);var resizedDot=dot.Copy();FreeCanvasGeometry.Resize(resizedDot,dot,"se",new Point(900,180),1);check(resizedDot.Points.Count==1&&FreeCanvasStore.Finite(resizedDot.Points[0].X)&&resizedDot.Bounds().Width==dot.Stroke,"resizing a pen dot keeps a finite round point rather than producing an invalid zero-length path");
    string gestureData=Path.Combine(root,"save-gesture");saveGesture=new FreeCanvasWindow(gestureData,new Settings());var moving=original.Copy();saveGesture.DrawItemForTests(moving);saveGesture.BeginMoveForTests(moving.Id,new Vector(25,13));check(saveGesture.SaveForTests(),"explicit save settles an in-progress move before writing its geometry");saveGesture.CancelGestureForTests();var gestureStore=new FreeCanvasStore(gestureData);var savedMove=gestureStore.Load(saveGesture.DocumentForTests.Id);check(!saveGesture.DirtyForTests&&savedMove.Items[0].Points[0].X==55&&savedMove.Items[0].Points[0].Y==53&&saveGesture.DocumentForTests.Items[0].Points[0].X==savedMove.Items[0].Points[0].X,"cancel after explicit save cannot leave disk and visible geometry at different positions");saveGesture.UndoForTests();check(saveGesture.DocumentForTests.Items[0].Points[0].X==30&&saveGesture.SaveForTests()&&gestureStore.Load(saveGesture.DocumentForTests.Id).Items[0].Points[0].X==30,"move committed by save remains undoable and undo persists the original position");
    saveGesture.DrawItemForTests(new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="line",Color="auto",Stroke=2,X=20,Y=30,EndX=40,EndY=60});var keep=saveGesture.DocumentForTests.Items;var budgetPoints=Enumerable.Range(0,100000).Select(i=>new FreeCanvasPoint{X=i,Y=i}).ToList();saveGesture.DocumentForTests.Items=Enumerable.Range(0,10).Select(i=>new FreeCanvasItem{Id=Guid.NewGuid().ToString("N"),Kind="stroke",Color="auto",Stroke=2,Points=budgetPoints}).ToList();check(!saveGesture.BeginDrawingForTests("stroke",new Point(10,10))&&saveGesture.SavePendingForTests,"a full point budget refuses new drawing without stopping pending autosave");saveGesture.SurfaceForTests.RaiseEvent(new MouseButtonEventArgs(Mouse.PrimaryDevice,Environment.TickCount,MouseButton.Left){RoutedEvent=UIElement.MouseDownEvent});check(saveGesture.SavePendingForTests,"actual rejected mouse-down keeps prior edits scheduled for autosave");saveGesture.DocumentForTests.Items=keep;saveGesture.Close();saveGesture=null;
    window.Close();window=null;reloaded=new FreeCanvasWindow(data,new Settings());check(reloaded.DocumentForTests.Items.Count==saved.Items.Count&&reloaded.DocumentForTests.Items.Any(i=>i.Kind=="stroke")&&!reloaded.IsVisible,"reopening saved project restores annotations without showing a desktop test window");
   }finally{if(window!=null)window.Close();if(reloaded!=null)reloaded.Close();if(saveGesture!=null)saveGesture.Close();Theme.Set(theme);Theme.SetAccent(accent);app.ShutdownMode=shutdown;}
  }
 }
}
